import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import {
  FaArrowLeft,
  FaArrowRight,
  FaArrowRight as FaArrow,
} from "react-icons/fa";
import { bannerAPI } from "../../utils/api";
import "./BannerSlider.css";

const BannerSlider = () => {
  const [banners, setBanners] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchBanners();
  }, []);

  useEffect(() => {
    if (banners.length > 1) {
      const interval = setInterval(() => {
        setCurrentIndex((prevIndex) => (prevIndex + 1) % banners.length);
      }, 5000); // Auto-advance every 5 seconds

      return () => clearInterval(interval);
    }
  }, [banners.length]);

  const fetchBanners = async () => {
    try {
      setLoading(true);
      const response = await bannerAPI.getAll();
      console.log("Banner API response:", response);
      // Filter active banners if needed, or use all banners
      const activeBanners = response.data.data || response.data || [];
      console.log("Active banners:", activeBanners);
      setBanners(activeBanners);
    } catch (error) {
      console.error("Error fetching banners:", error);
      // Set some default banners for development/testing
      setBanners([
        {
          id: 1,
          title: "Welcome to PowerFuel",
          description: "Premium supplements for your fitness journey",
          image: "https://via.placeholder.com/1200x400?text=PowerFuel+Supplements",
          buttonText: "Shop Now",
          link: "/products"
        }
      ]);
    } finally {
      setLoading(false);
    }
  };

  const nextSlide = () => {
    setCurrentIndex((prevIndex) => (prevIndex + 1) % banners.length);
  };

  const prevSlide = () => {
    setCurrentIndex(
      (prevIndex) => (prevIndex - 1 + banners.length) % banners.length
    );
  };

  const goToSlide = (index) => {
    setCurrentIndex(index);
  };

  if (loading) {
    return (
      <div className="banner-slider">
        <div className="banner-slide">
          <div className="banner-content">
            <div className="loading-spinner">
              <div className="spinner"></div>
              <p>Loading banners...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (banners.length === 0) {
    // Show a default banner if no banners are available
    return (
      <div className="banner-slider">
        <div className="banner-slide">
          <div className="banner-image">
            <img
              src="https://via.placeholder.com/1200x400?text=PowerFuel+Supplements"
              alt="PowerFuel Supplements"
            />
          </div>
          <div className="banner-content">
            <div className="banner-text">
              <h1 className="banner-title">Welcome to PowerFuel</h1>
              <p className="banner-description">Premium supplements for your fitness journey</p>
              <Link to="/products" className="btn btn-primary banner-btn">
                Shop Now
                <FaArrow />
              </Link>
            </div>
          </div>
        </div>
      </div>
    );
  }

  const currentBanner = banners[currentIndex];

  return (
    <div className="banner-slider">
      <div className="banner-slide">
        <div className="banner-image">
          <img
            src={currentBanner.image?.startsWith('http') ? currentBanner.image : `/images/${currentBanner.image}`}
            alt={currentBanner.title}
            onError={(e) => {
              e.target.src = "https://via.placeholder.com/1200x400?text=PowerFuel+Supplements";
            }}
          />
        </div>
        <div className="banner-content">
          <div className="banner-text">
            <h1 className="banner-title">{currentBanner.title}</h1>
            <p className="banner-description">{currentBanner.description}</p>
            {currentBanner.buttonText && (
              <Link
                to={currentBanner.link || "/products"}
                className="btn btn-primary banner-btn"
              >
                {currentBanner.buttonText}
                <FaArrow />
              </Link>
            )}
          </div>
        </div>

        {/* Navigation arrows */}
        {banners.length > 1 && (
          <>
            <button className="banner-nav banner-prev" onClick={prevSlide}>
              <FaArrowLeft />
            </button>
            <button className="banner-nav banner-next" onClick={nextSlide}>
              <FaArrowRight />
            </button>
          </>
        )}

        {/* Dots indicator */}
        {banners.length > 1 && (
          <div className="banner-dots">
            {banners.map((_, index) => (
              <button
                key={index}
                className={`banner-dot ${
                  index === currentIndex ? "active" : ""
                }`}
                onClick={() => goToSlide(index)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default BannerSlider;
